//! The git oracle corpus (PLAN.md §A4.8), generated by `script/gen-oracle`.
//!
//! These tests check the corpus itself, then compare the alignment against it in both modes,
//! then parse git's markers back into its inputs.

use std::collections::HashSet;
use std::ops::Range;

use merge_core::document::{Labels, MergeDocument, MergeOptions, Output};
use merge_core::markers::{self, MarkerError};
use merge_core::merge3::{Inputs, Kind, LEFT, Refine, Region, align};
use merge_core::text::Text;
use serde::Deserialize;

const CORPUS: &str = include_str!("../../../fixtures/oracle/corpus.jsonl");

// Counts from `script/gen-oracle`: its SEEDS list, MUTATION_CASES, and two cases per HISTORY entry.
const SEED_CASES: usize = 45;
const MUTATION_CASES: usize = 1900;
const HISTORY_CASES: usize = 10;
const DEFAULT_MARKER_SIZE: usize = 7;

/// Cases where the alignment differs from git, with the reason (spec §8.3).
///
/// - `mutation-1623`: git re-diffs a histogram group that moved while sliding, using its
///   Myers diff. On `a b { b` against `b c d a` git's Myers keeps the last `b`; imara-diff's
///   keeps the first. Both diffs cost the same; the conflict lands one line apart.
const KNOWN_DIVERGENCES: [&str; 2] = ["mutation-1623 diff3", "mutation-1623 zdiff3"];

#[derive(Debug, Deserialize)]
struct Case {
    id: String,
    base: String,
    left: String,
    right: String,
    marker_size: usize,
    diff3: Merge,
    zdiff3: Merge,
    /// git's default style: two-way markers, no base section.
    merge: Merge,
}

#[derive(Debug, Deserialize)]
struct Merge {
    exit: usize,
    output: String,
    /// The output with every conflict resolved to the left side (`--ours`).
    ours: String,
    /// The output with every conflict resolved to the right side (`--theirs`).
    theirs: String,
}

impl Case {
    fn merges(&self) -> [(&'static str, &Merge); 2] {
        [("diff3", &self.diff3), ("zdiff3", &self.zdiff3)]
    }

    fn marker(&self, c: char, label: &str) -> String {
        let run = c.to_string().repeat(self.marker_size);
        if label.is_empty() { run } else { format!("{run} {label}") }
    }
}

fn corpus() -> Vec<Case> {
    CORPUS.lines().map(|line| serde_json::from_str(line).expect("corpus line parses")).collect()
}

/// Whether `l` is `line` followed by `\n` or `\r\n`: git ends marker lines in CRLF when the
/// file around the conflict does.
fn is_line(l: &str, line: &str) -> bool {
    let body = l.strip_suffix('\n');
    body == Some(line) || body.and_then(|b| b.strip_suffix('\r')) == Some(line)
}

fn count_lines(text: &str, line: &str) -> usize {
    text.split_inclusive('\n').filter(|l| is_line(l, line)).count()
}

#[test]
fn corpus_holds_every_source_with_unique_ids() {
    let cases = corpus();
    let count = |prefix: &str| cases.iter().filter(|c| c.id.starts_with(prefix)).count();
    assert_eq!(
        (count("seed-"), count("mutation-"), count("history-")),
        (SEED_CASES, MUTATION_CASES, HISTORY_CASES)
    );
    assert_eq!(cases.len(), SEED_CASES + MUTATION_CASES + HISTORY_CASES);
    let ids: HashSet<&str> = cases.iter().map(|c| c.id.as_str()).collect();
    assert_eq!(ids.len(), cases.len(), "ids are unique");
}

#[test]
fn exit_code_counts_each_kind_of_conflict_marker() {
    for case in corpus() {
        assert!(case.marker_size >= DEFAULT_MARKER_SIZE, "{}", case.id);
        for (mode, merge) in case.merges() {
            for line in [
                case.marker('<', "left"),
                case.marker('|', "base"),
                case.marker('=', ""),
                case.marker('>', "right"),
            ] {
                assert_eq!(
                    count_lines(&merge.output, &line),
                    merge.exit,
                    "{} {mode}: {line:?}",
                    case.id
                );
            }
        }
    }
}

#[test]
fn a_side_equal_to_base_gives_the_other_side_cleanly() {
    let mut checked = 0;
    for case in corpus() {
        let expected = if case.left == case.base {
            &case.right
        } else if case.right == case.base {
            &case.left
        } else {
            continue;
        };
        checked += 1;
        for (mode, merge) in case.merges() {
            assert_eq!((merge.exit, &merge.output), (0, expected), "{} {mode}", case.id);
        }
    }
    assert!(checked > 0, "the corpus has cases with an unchanged side");
}

#[test]
fn identical_sides_merge_cleanly_to_that_side() {
    let mut checked = 0;
    for case in corpus().iter().filter(|c| c.left == c.right) {
        checked += 1;
        for (mode, merge) in case.merges() {
            assert_eq!((merge.exit, &merge.output), (0, &case.left), "{} {mode}", case.id);
        }
    }
    assert!(checked > 0, "the corpus has cases with identical sides");
}

#[test]
fn git_ends_markers_in_crlf_when_both_sides_and_base_do() {
    let cases = corpus();
    let case = cases.iter().find(|c| c.id == "seed-crlf-mixed-conflict").expect("seed case exists");
    // base a,b and left a,L end in CRLF; right ends R in LF after a CRLF first line.
    assert_eq!(
        case.diff3.output,
        "a\r\n<<<<<<< left\r\nL\r\n||||||| base\r\nb\r\n=======\r\nR\n>>>>>>> right\r\n"
    );
}

fn decode(s: &str) -> Text {
    Text::decode(s.as_bytes()).expect("corpus text decodes")
}

fn lines(text: &Text, range: &Range<usize>) -> String {
    range.clone().map(|n| text.line(n)).collect()
}

/// The automatic text of a region that is not a conflict.
fn auto_text(inputs: &Inputs, region: &Region) -> String {
    match region.kind {
        Kind::Unchanged => lines(&inputs.bases()[0], &region.bases[0]),
        Kind::OneSide(i) => lines(&inputs.sides()[i], &region.sides[i]),
        Kind::AllSame => lines(&inputs.sides()[LEFT], &region.sides[LEFT]),
        Kind::Conflict => unreachable!("conflicts have no automatic text"),
        Kind::WordMerged => unreachable!("git's corpus merges line by line"),
    }
}

/// The automatic text between conflicts: one more segment than there are conflicts.
fn segments_between_conflicts(inputs: &Inputs, regions: &[Region]) -> Vec<String> {
    regions
        .split(|r| r.kind == Kind::Conflict)
        .map(|run| run.iter().map(|r| auto_text(inputs, r)).collect())
        .collect()
}

/// git's output outside its conflict markers, split at each conflict.
fn segments_outside_markers(case: &Case, output: &str) -> Vec<String> {
    let (open, close) = (case.marker('<', "left"), case.marker('>', "right"));
    let mut segments = vec![String::new()];
    let mut inside = false;
    for line in output.split_inclusive('\n') {
        if inside {
            if is_line(line, &close) {
                inside = false;
                segments.push(String::new());
            }
        } else if is_line(line, &open) {
            inside = true;
        } else {
            segments.last_mut().expect("starts with a segment").push_str(line);
        }
    }
    segments
}

#[test]
fn alignment_matches_git_outside_conflicts_in_both_modes() {
    let failures: Vec<String> = corpus()
        .iter()
        .flat_map(|case| {
            let inputs =
                Inputs::three_way(decode(&case.base), decode(&case.left), decode(&case.right));
            [(Refine::Off, &case.diff3, "diff3"), (Refine::Ends, &case.zdiff3, "zdiff3")]
                .into_iter()
                .filter_map(move |(refine, merge, mode)| {
                    let regions = align(
                        &inputs,
                        MergeOptions { refine, ..MergeOptions::default() }.alignment(),
                    );
                    let conflicts = regions.iter().filter(|r| r.kind == Kind::Conflict).count();
                    let ours = (conflicts, segments_between_conflicts(&inputs, &regions));
                    let git = (merge.exit, segments_outside_markers(case, &merge.output));
                    (ours != git).then(|| format!("{} {mode}", case.id))
                })
                .collect::<Vec<_>>()
        })
        .collect();
    assert_eq!(failures, KNOWN_DIVERGENCES);
}

#[test]
fn output_matches_git_byte_for_byte_in_both_modes() {
    let failures: Vec<String> = corpus()
        .iter()
        .flat_map(|case| {
            [(Refine::Off, &case.diff3, "diff3"), (Refine::Ends, &case.zdiff3, "zdiff3")]
                .into_iter()
                .filter_map(move |(refine, merge, mode)| {
                    let inputs = Inputs::three_way(
                        decode(&case.base),
                        decode(&case.left),
                        decode(&case.right),
                    );
                    let options = MergeOptions { refine, ..MergeOptions::default() };
                    let doc = MergeDocument::new(
                        inputs,
                        options,
                        Labels::three_way("left", "base", "right"),
                    )
                    .expect("three labels fit");
                    let ours = (doc.marker_length(), doc.output());
                    let git_output = if merge.exit == 0 {
                        Output::Resolved(merge.output.clone())
                    } else {
                        Output::Conflicted(merge.output.clone())
                    };
                    let git = (case.marker_size, git_output);
                    (ours != git).then(|| format!("{} {mode}", case.id))
                })
                .collect::<Vec<_>>()
        })
        .collect();
    assert_eq!(failures, KNOWN_DIVERGENCES);
}

/// git's three marker styles.
fn styles(case: &Case) -> [(&'static str, &Merge); 3] {
    [("diff3", &case.diff3), ("zdiff3", &case.zdiff3), ("merge", &case.merge)]
}

/// The base a marker parse must give: git's output with each conflict replaced by its base
/// section, or by nothing in the merge style. Marker lines match exactly, at the case's size
/// and with its labels.
fn base_from_markers(case: &Case, output: &str) -> String {
    let open = case.marker('<', "left");
    let ancestor = case.marker('|', "base");
    let separator = case.marker('=', "");
    let close = case.marker('>', "right");
    let mut base = String::new();
    // Outside a conflict, and in a conflict's base section, lines belong to the base.
    let mut keep = true;
    for line in output.split_inclusive('\n') {
        if is_line(line, &open) || is_line(line, &separator) {
            keep = false;
        } else if is_line(line, &ancestor) || is_line(line, &close) {
            keep = true;
        } else if keep {
            base.push_str(line);
        }
    }
    base
}

/// A side as git's markers hold it. git ends a section without a final newline with the
/// marker line ending before writing the next marker; the markers keep no record that the
/// side had none. In the corpus such a section always ends the file, in its last conflict.
fn as_marked(side: &str, output: &str) -> String {
    let close = output.split_inclusive('\n').next_back().filter(|line| line.starts_with('>'));
    match close {
        Some(line) if !side.is_empty() && !side.ends_with('\n') => {
            let ending = if line.ends_with("\r\n") { "\r\n" } else { "\n" };
            format!("{side}{ending}")
        }
        _ => side.to_owned(),
    }
}

#[test]
fn parsing_gits_markers_gives_its_ours_base_and_theirs_in_every_style() {
    let mut checked = 0;
    let failures: Vec<String> = corpus()
        .iter()
        .flat_map(|case| {
            styles(case)
                .into_iter()
                .filter(|(_, merge)| merge.exit > 0)
                .filter_map(|(mode, merge)| {
                    checked += 1;
                    let parsed = markers::parse(&decode(&merge.output)).map(|p| {
                        let content = |t: &[Text]| -> Vec<String> {
                            t.iter().map(|t| t.content().to_owned()).collect()
                        };
                        (
                            content(p.inputs.sides()),
                            content(p.inputs.bases()),
                            p.labels,
                            p.marker_length,
                        )
                    });
                    let git = Ok((
                        vec![
                            as_marked(&merge.ours, &merge.output),
                            as_marked(&merge.theirs, &merge.output),
                        ],
                        vec![base_from_markers(case, &merge.output)],
                        // The corpus's base label is jj's default, which titles no pane.
                        Labels::three_way("left", "", "right"),
                        case.marker_size,
                    ));
                    (parsed != git).then(|| format!("{} {mode} {parsed:?} != {git:?}", case.id))
                })
                .collect::<Vec<_>>()
        })
        .collect();
    assert_eq!(failures, Vec::<String>::new());
    assert!(checked > 0, "the corpus has conflicts");
}

/// Whether `line` reads as a conflict's start: a run of at least the default marker size of
/// `<`, then whitespace or the line's end.
fn opens_like_a_marker(line: &str) -> bool {
    let rest = line.trim_start_matches('<');
    line.len() - rest.len() >= DEFAULT_MARKER_SIZE
        && rest.chars().next().is_none_or(char::is_whitespace)
}

/// A clean merge holds no conflict. Its marker-like lines, from the seeds, open conflicts that
/// never close or that nest, which the parse refuses.
#[test]
fn gits_clean_output_never_parses_as_a_conflict() {
    let mut marker_like = 0;
    let failures: Vec<String> = corpus()
        .iter()
        .flat_map(|case| {
            styles(case)
                .into_iter()
                .filter(|(_, merge)| merge.exit == 0)
                .filter_map(|(mode, merge)| {
                    let parsed = markers::parse(&decode(&merge.output)).map(|p| p.marker_length);
                    let fits = if merge.output.split_inclusive('\n').any(opens_like_a_marker) {
                        marker_like += 1;
                        matches!(
                            parsed,
                            Err(MarkerError::Unclosed { .. } | MarkerError::Nested { .. })
                        )
                    } else {
                        parsed == Err(MarkerError::NoMarkers)
                    };
                    (!fits).then(|| format!("{} {mode} {parsed:?}", case.id))
                })
                .collect::<Vec<_>>()
        })
        .collect();
    assert_eq!(failures, Vec::<String>::new());
    assert!(marker_like > 0, "the corpus has clean merges with marker-like lines");
}
